gKE(){return"\u092e\u0948\u0902 \u0907\u0928 \u0936\u0930\u094d\u0924\u094b\u0902 \u0915\u094b \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u0930\u0924\u093e/\u0915\u0930\u0924\u0940 \u0939\u0942\u0901 \u0914\u0930 \u0907\u0938 \u0938\u092e\u091d\u094c\u0924\u0947 \u0915\u0947 \u0905\u092a\u0928\u0947 \u0939\u093f\u0938\u094d\u0938\u0947 \u0915\u094b \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0928\u093f\u092d\u093e\u090a\u0901\u0917\u093e/\u0928\u093f\u092d\u093e\u090a\u0901\u0917\u0940\u0964 \u092e\u0948\u0902 \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0930\u0924\u093e/\u0915\u0930\u0924\u0940 \u0939\u0942\u0901 \u0915\u093f \u092e\u0948\u0902 \u0915\u093e\u0928\u0942\u0928\u0940 \u0930\u0942\u092a \u0938\u0947 \u092f\u0939 \u0915\u093e\u092e \u0915\u0930 \u0938\u0915\u0924\u093e/\u0938\u0915\u0924\u0940 \u0939\u0942\u0901, \u092e\u0947\u0930\u0947 \u092a\u093e\u0938 \u0906\u0935\u0936\u094d\u092f\u0915 \u092f\u094b\u0917\u094d\u092f\u0924\u093e, \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0914\u0930 \u092a\u0930\u092e\u093f\u091f \u0939\u0948\u0902, \u0914\u0930 \u092e\u0948\u0902 \u092a\u094d\u0930\u092e\u093e\u0923 \u0938\u093e\u0925 \u0930\u0916\u0942\u0901\u0917\u093e/\u0930\u0916\u0942\u0901\u0917\u0940 \u0924\u0925\u093e \u0917\u094d\u0930\u093e\u0939\u0915 \u0915\u0947 \u092e\u093e\u0901\u0917\u0928\u0947 \u092a\u0930 \u0926\u093f\u0916\u093e\u090a\u0901\u0917\u093e/\u0926\u093f\u0916\u093e\u090a\u0901\u0917\u0940\u0964"},
gKD(){return"\u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u0930\u0947\u0902"},
gKF(){return"\u0915\u094d\u092f\u093e \u0906\u092a \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u0915\u093f \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930\u093f\u0924 \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0915\u0940 \u0936\u0930\u094d\u0924\u094b\u0902 \u092a\u0930 \u092f\u0939 \u0911\u0930\u094d\u0921\u0930 \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902?"},
gL6(){return"\u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0935\u093e\u092a\u0938 \u0932\u0947\u0915\u0930 \u0911\u0930\u094d\u0921\u0930 \u0905\u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u0930\u0947\u0902?"},
gL5(){return"\u0907\u0938\u0938\u0947 \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u093f\u0924 \u0938\u092e\u091d\u094c\u0924\u093e \u0930\u0926\u094d\u0926 \u0939\u094b\u0917\u093e\u0964 \u0906\u092a\u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0935\u093e\u092a\u0938 \u0932\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e, \u0917\u094d\u0930\u093e\u0939\u0915 \u0915\u094b \u0938\u0942\u091a\u0928\u093e \u092e\u093f\u0932\u0947\u0917\u0940 \u0914\u0930 \u0907\u0938\u0947 \u092a\u0942\u0930\u094d\u0935\u0935\u0924 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0947\u0917\u093e\u0964"},
gL4(){return"\u0930\u0926\u094d\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0935\u093e\u092a\u0938 \u0932\u0947\u0902"},
gL7(){return"\u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0915\u0940 \u0936\u0930\u094d\u0924\u0947\u0902 \u0932\u094b\u0921 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0940\u0902\u0964 \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u091c\u093e\u0901\u091a\u0915\u0930 \u092b\u093f\u0930 \u0915\u094b\u0936\u093f\u0936 \u0915\u0930\u0947\u0902\u0964"},
gLd(){return"\u0906\u092a\u0915\u093e \u0928\u093f\u0930\u094d\u0923\u092f \u0938\u0939\u0947\u091c\u093e \u0928\u0939\u0940\u0902 \u091c\u093e \u0938\u0915\u093e\u0964 \u0911\u0930\u094d\u0921\u0930 \u0915\u0940 \u092e\u094c\u091c\u0942\u0926\u093e \u0938\u094d\u0925\u093f\u0924\u093f \u091c\u093e\u0901\u091a\u0915\u0930 \u092b\u093f\u0930 \u0915\u094b\u0936\u093f\u0936 \u0915\u0930\u0947\u0902\u0964"},
