gMx(){return"\u041d\u0435 \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u0434\u0430\u0432\u0430\u0442\u044c \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f"},
gMw(){return"\u041d\u0435 \u043c\u043e\u0436\u0435\u0442 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f"},
gGp(){return"\u0414\u0438\u0430\u043b\u043e\u0433 \u0436\u0430\u043b\u043e\u0431\u044b"},
Gc(a){return"\u0416\u0430\u043b\u043e\u0431\u0430: \xab"+a+"\xbb"},
Gd(a,b){return a+" ("+b+")"},
gGr(){return"\u0416\u0430\u043b\u043e\u0431\u044b"},
gGq(){return"\u041f\u043e \u044d\u0442\u043e\u043c\u0443 \u0437\u0430\u043a\u0430\u0437\u0443 \u0440\u0430\u043d\u0435\u0435 \u0431\u044b\u043b\u0430 \u043f\u043e\u0434\u0430\u043d\u0430 \u0436\u0430\u043b\u043e\u0431\u0430, \u043d\u043e \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u0443\u043b\u0430\u0436\u0435\u043d. \u0417\u0430\u043a\u0440\u044b\u0442\u0430\u044f \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u043a\u0430 \u0441\u043a\u0440\u044b\u0442\u0430 \u0438 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u0430 \u0432 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442."},
gG6(){return"\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u043c \u0434\u0438\u0430\u043b\u043e\u0433 \u0436\u0430\u043b\u043e\u0431\u044b\u2026"},
gG5(){return"\u0414\u0438\u0430\u043b\u043e\u0433 \u0436\u0430\u043b\u043e\u0431\u044b \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d"},
gG4(){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0434\u0438\u0430\u043b\u043e\u0433 \u0436\u0430\u043b\u043e\u0431\u044b. \u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0435\u0449\u0451 \u0440\u0430\u0437."},
gFR(){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0441 \u0436\u0430\u043b\u043e\u0431\u043e\u0439. \u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0435\u0449\u0451 \u0440\u0430\u0437."},
gGu(){return"\u042d\u0442\u043e\u0442 \u0434\u0438\u0430\u043b\u043e\u0433 \u043e\u0431\u0449\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d"},
gGt(){return"\u0410\u043a\u0442\u0438\u0432\u043d\u0443\u044e \u0436\u0430\u043b\u043e\u0431\u0443 \u0432\u0438\u0434\u044f\u0442 \u0432\u0441\u0435, \u043a\u043e\u043c\u0443 \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u0437\u0430\u043a\u0430\u0437. \u041f\u0438\u0448\u0438\u0442\u0435 \u0432\u0435\u0436\u043b\u0438\u0432\u043e \u0438 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e, \u043d\u0435 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0439\u0442\u0435 \u043b\u0438\u0447\u043d\u044b\u0435 \u0438\u043b\u0438 \u043f\u043b\u0430\u0442\u0451\u0436\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435. \u041f\u043e\u043a\u0430 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u043d\u0435 \u0443\u043b\u0430\u0436\u0435\u043d, \u0436\u0430\u043b\u043e\u0431\u0430 \u043c\u043e\u0436\u0435\u0442 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0432\u043b\u0438\u044f\u0442\u044c \u043d\u0430 \u0440\u0435\u0439\u0442\u0438\u043d\u0433 \u043e\u0431\u0435\u0438\u0445 \u0441\u0442\u043e\u0440\u043e\u043d."},
GB(a){return"\u041f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0430\u044f \u0436\u0430\u043b\u043e\u0431\u0430 \u0431\u044b\u043b\u0430 \u0443\u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0430 ("+a+"). \u0415\u0451 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u0441\u043a\u0440\u044b\u0442\u044b."},
gGf(){return"\u0410\u043a\u0442\u0438\u0432\u043d\u043e\u0439 \u0436\u0430\u043b\u043e\u0431\u044b \u043d\u0435\u0442. \u041f\u043e\u043a\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0441\u0440\u043e\u043a \u043f\u043e\u0434\u0430\u0447\u0438, \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u0435\u0451 \u043c\u043e\u0436\u0435\u0442 \u043b\u044e\u0431\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430."},
gGF(){return"\u041f\u043e\u0434\u0430\u0442\u044c \u0436\u0430\u043b\u043e\u0431\u0443"},
gGx(){return"\u041d\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u043e\u0442\u0432\u0435\u0442"},
gG2(){return"\u041e\u043f\u0438\u0448\u0438\u0442\u0435, \u0447\u0442\u043e \u043f\u0440\u043e\u0438\u0437\u043e\u0448\u043b\u043e, \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u044f \u0438 \u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u044b\u0439 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u0448\u0430\u0433, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043f\u043e\u043c\u043e\u0436\u0435\u0442 \u0443\u043c\u0435\u043d\u044c\u0448\u0438\u0442\u044c \u0438\u043b\u0438 \u0443\u0441\u0442\u0440\u0430\u043d\u0438\u0442\u044c \u043f\u043e\u0442\u0435\u0440\u0438 \u0434\u0440\u0443\u0433\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b. \u041f\u0438\u0448\u0438\u0442\u0435 \u0443\u0432\u0430\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0438 \u043f\u043e \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443."},
gG8(){return"\u041f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0436\u0430\u043b\u043e\u0431\u044b"},
gG7(){return"\u041a\u0440\u0430\u0442\u043a\u043e \u043e\u043f\u0438\u0448\u0438\u0442\u0435 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0443 \u0438\u043b\u0438 \u043e\u0442\u0432\u0435\u0442\u044c\u0442\u0435 \u043d\u0430 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u044e\u044e \u043f\u0440\u0435\u0442\u0435\u043d\u0437\u0438\u044e \u0444\u0430\u043a\u0442\u0430\u043c\u0438, \u0437\u0430\u0442\u0435\u043c \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u0442\u0435 \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u043d\u044b\u0439 \u0441\u043f\u043e\u0441\u043e\u0431 \u0443\u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u0438 \u043c\u0438\u043d\u0438\u043c\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e\u0442\u0435\u0440\u0438 \u043e\u0431\u0435\u0438\u0445 \u0441\u0442\u043e\u0440\u043e\u043d."},
