gLM(){return"\u041e\u043f\u0438\u0448\u0456\u0442\u044c \u0441\u0432\u043e\u0454 \u0431\u0430\u0447\u0435\u043d\u043d\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0438 \u0440\u043e\u0437\u0456\u0440\u0432\u0430\u043d\u043d\u044f, \u0435\u0442\u0430\u043f \u0432\u0438\u043a\u043e\u043d\u0430\u043d\u043d\u044f \u0440\u043e\u0431\u0456\u0442 \u0456 \u0434\u043e\u0441\u0432\u0456\u0434 \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u0456 \u0456\u0437 \u0437\u0430\u043c\u043e\u0432\u043d\u0438\u043a\u043e\u043c."},
gLD(){return"\u041e\u043f\u0438\u0448\u0456\u0442\u044c \u0441\u0432\u043e\u0454 \u0431\u0430\u0447\u0435\u043d\u043d\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0438 \u043f\u0440\u0438\u043f\u0438\u043d\u0435\u043d\u043d\u044f \u0440\u043e\u0431\u0456\u0442 \u0456 \u0440\u043e\u0437\u0456\u0440\u0432\u0430\u043d\u043d\u044f \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0443, \u0435\u0442\u0430\u043f \u0432\u0438\u043a\u043e\u043d\u0430\u043d\u043d\u044f \u0442\u0430 \u0434\u043e\u0441\u0432\u0456\u0434 \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u0456 \u0437 \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u0435\u043c."},
gMc(){return"\u041f\u0456\u0437\u043d\u0456\u0448\u0435"},
gLI(){return"\u0417\u0430\u043b\u0438\u0448\u0438\u0442\u0438 \u0441\u0432\u0456\u0439 \u0432\u0456\u0434\u0433\u0443\u043a"},
gMe(){return"\u0412\u0430\u0448\u0443 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u044c \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e."},
gMb(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0437\u0431\u0435\u0440\u0435\u0433\u0442\u0438 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u044c. \u041f\u043e\u0432\u0442\u043e\u0440\u0456\u0442\u044c \u0441\u043f\u0440\u043e\u0431\u0443."},
gLt(){return"\u041a\u043e\u043c\u0435\u043d\u0442\u0430\u0440 \u043c\u0430\u0454 \u043c\u0456\u0441\u0442\u0438\u0442\u0438 \u0449\u043e\u043d\u0430\u0439\u043c\u0435\u043d\u0448\u0435 5 \u0441\u0438\u043c\u0432\u043e\u043b\u0456\u0432."},
