gLf(){return"\u0420\u043e\u0431\u043e\u0442\u0443 \u0432\u0441\u0435 \u0449\u0435 \u043c\u043e\u0436\u043d\u0430 \u0432\u0438\u043a\u043e\u043d\u0430\u0442\u0438"},
gLg(){return"\u041d\u0456\u0447\u043e\u0433\u043e \u0441\u0442\u0440\u0430\u0448\u043d\u043e\u0433\u043e: \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0441\u043a\u0430\u0441\u043e\u0432\u0430\u043d\u043e, \u0430\u043b\u0435 \u0432\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u043e\u043f\u0443\u0431\u043b\u0456\u043a\u0443\u0432\u0430\u0442\u0438 \u0439\u043e\u0433\u043e \u0442\u043e\u0447\u043d\u0443 \u043a\u043e\u043f\u0456\u044e \u0442\u0430 \u0434\u043e\u0447\u0435\u043a\u0430\u0442\u0438\u0441\u044f \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u0439 \u0456\u043d\u0448\u0438\u0445 \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u0456\u0432. \u0414\u043b\u044f \u0446\u044c\u043e\u0433\u043e \u043d\u0430\u0442\u0438\u0441\u043d\u0456\u0442\u044c \xab\u041f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u0438\xbb."},
gSd(){return"\u0417\u0430\u043c\u043e\u0432\u043d\u0438\u043a \u0437\u0430\u0431\u043b\u043e\u043a\u0443\u0432\u0430\u0432 \u0434\u043b\u044f \u0432\u0430\u0441 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u0457 \u0442\u0430 \u043b\u0438\u0441\u0442\u0443\u0432\u0430\u043d\u043d\u044f \u0432 \u0446\u044c\u043e\u043c\u0443 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u043c\u0443 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u0456."},
