gMy(){return"\u041f\u043e\u043f\u0435\u0440\u0435\u0434\u043d\u0456\u0439 \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0435\u0446\u044c"},
gMx(){return"\u041d\u0435 \u043c\u043e\u0436\u0435 \u043f\u043e\u0434\u0430\u0432\u0430\u0442\u0438 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u0457"},
gMw(){return"\u041d\u0435 \u043c\u043e\u0436\u0435 \u043d\u0430\u0434\u0441\u0438\u043b\u0430\u0442\u0438 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f"},
