gWc(){return"\u041a\u043e\u0440\u043e\u0442\u043a\u043e \u0432\u043a\u0430\u0436\u0456\u0442\u044c \u0441\u0432\u043e\u044e \u043f\u0440\u043e\u0444\u0435\u0441\u0456\u044e \u0442\u0430 \u0441\u043f\u0435\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044e, \u043d\u0430\u043f\u0440\u0438\u043a\u043b\u0430\u0434 \xab\u0421\u0430\u043d\u0442\u0435\u0445\u043d\u0456\u043a \u0434\u043b\u044f \u0436\u0438\u0442\u043b\u043e\u0432\u0438\u0445 \u0431\u0443\u0434\u0438\u043d\u043a\u0456\u0432 \u0443 \u0422\u043e\u0440\u043e\u043d\u0442\u043e\xbb."},
gVZ(){return"\u0420\u043e\u0437\u043a\u0430\u0436\u0456\u0442\u044c \u043f\u0440\u043e \u0441\u0435\u0431\u0435, \u0441\u0432\u0456\u0439 \u043f\u0456\u0434\u0445\u0456\u0434 \u0434\u043e \u0440\u043e\u0431\u043e\u0442\u0438, \u0449\u043e \u0434\u043b\u044f \u0432\u0430\u0441 \u0432\u0430\u0436\u043b\u0438\u0432\u043e \u0442\u0430 \u0447\u043e\u0433\u043e \u0437\u0430\u043c\u043e\u0432\u043d\u0438\u043a\u0438 \u043c\u043e\u0436\u0443\u0442\u044c \u043e\u0447\u0456\u043a\u0443\u0432\u0430\u0442\u0438 \u0432\u0456\u0434 \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u0456."},
gWl(){return"\u041f\u0435\u0440\u0435\u043b\u0456\u0447\u0456\u0442\u044c \u043f\u043e\u0441\u043b\u0443\u0433\u0438 \u0439 \u0432\u0438\u0434\u0438 \u0440\u043e\u0431\u0456\u0442, \u044f\u043a\u0456 \u0432\u0438\u043a\u043e\u043d\u0443\u0454\u0442\u0435. \u0423\u043a\u0430\u0436\u0456\u0442\u044c \u0441\u043f\u0435\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044e, \u043e\u0431\u043b\u0430\u0434\u043d\u0430\u043d\u043d\u044f \u0442\u0430 \u0437\u0430\u0432\u0434\u0430\u043d\u043d\u044f, \u0443 \u044f\u043a\u0438\u0445 \u043c\u0430\u0454\u0442\u0435 \u043d\u0430\u0439\u0431\u0456\u043b\u044c\u0448\u0435 \u0434\u043e\u0441\u0432\u0456\u0434\u0443."},
gWa(){return"\u0423\u043a\u0430\u0436\u0456\u0442\u044c \u0441\u0442\u0430\u0436 \u0443 \u0446\u0456\u0439 \u0441\u0444\u0435\u0440\u0456, \u0441\u0432\u043e\u0457 \u0440\u043e\u043b\u0456 \u0442\u0430 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u043d\u0456 \u043f\u0440\u043e\u0454\u043a\u0442\u0438. \u041e\u043f\u0438\u0448\u0456\u0442\u044c \u0432\u0438\u043a\u043e\u043d\u0430\u043d\u0456 \u0437\u0430\u0432\u0434\u0430\u043d\u043d\u044f \u0439 \u0434\u043e\u0441\u044f\u0433\u043d\u0443\u0442\u0456 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0438."},
gW7(){return"\u0423\u043a\u0430\u0436\u0456\u0442\u044c \u043f\u0440\u043e\u0444\u0456\u043b\u044c\u043d\u0443 \u043f\u0440\u043e\u0444\u0435\u0441\u0456\u0439\u043d\u0443 \u0430\u0431\u043e \u0432\u0438\u0449\u0443 \u043e\u0441\u0432\u0456\u0442\u0443: \u0437\u0430\u043a\u043b\u0430\u0434, \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u0443 \u0447\u0438 \u0441\u043f\u0435\u0446\u0456\u0430\u043b\u044c\u043d\u0456\u0441\u0442\u044c, \u043a\u0432\u0430\u043b\u0456\u0444\u0456\u043a\u0430\u0446\u0456\u044e \u0442\u0430 \u0440\u0456\u043a \u0437\u0430\u043a\u0456\u043d\u0447\u0435\u043d\u043d\u044f. \u0414\u0438\u043f\u043b\u043e\u043c\u0438 \u043c\u043e\u0436\u043d\u0430 \u0434\u043e\u0434\u0430\u0442\u0438 \u043d\u0438\u0436\u0447\u0435."},
gW3(){return"\u041f\u0435\u0440\u0435\u043b\u0456\u0447\u0456\u0442\u044c \u043a\u0443\u0440\u0441\u0438, \u0441\u0435\u043c\u0456\u043d\u0430\u0440\u0438 \u0439 \u043f\u0456\u0434\u0432\u0438\u0449\u0435\u043d\u043d\u044f \u043a\u0432\u0430\u043b\u0456\u0444\u0456\u043a\u0430\u0446\u0456\u0457, \u043f\u043e\u0432\u2019\u044f\u0437\u0430\u043d\u0456 \u0437 \u0432\u0430\u0448\u0438\u043c\u0438 \u043f\u043e\u0441\u043b\u0443\u0433\u0430\u043c\u0438. \u0423\u043a\u0430\u0436\u0456\u0442\u044c \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0442\u043e\u0440\u0430, \u0442\u0435\u043c\u0443, \u0440\u0456\u043a \u0456 \u0437\u0434\u043e\u0431\u0443\u0442\u0456 \u043d\u0430\u0432\u0438\u0447\u043a\u0438."},
gW1(){return"\u041f\u0435\u0440\u0435\u043b\u0456\u0447\u0456\u0442\u044c \u043f\u0440\u043e\u0444\u0435\u0441\u0456\u0439\u043d\u0456 \u0441\u0435\u0440\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u0438, \u043b\u0456\u0446\u0435\u043d\u0437\u0456\u0457 \u0442\u0430 \u0430\u043a\u0440\u0435\u0434\u0438\u0442\u0430\u0446\u0456\u0457. \u0423\u043a\u0430\u0436\u0456\u0442\u044c \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0446\u0456\u044e, \u0449\u043e \u0457\u0445 \u0432\u0438\u0434\u0430\u043b\u0430, \u0434\u0430\u0442\u0443 \u0432\u0438\u0434\u0430\u0447\u0456 \u0442\u0430 \u0441\u0442\u0440\u043e\u043a \u0434\u0456\u0457 \u0437\u0430 \u043d\u0430\u044f\u0432\u043d\u043e\u0441\u0442\u0456; \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u0434\u043e\u0434\u0430\u0439\u0442\u0435 \u043d\u0438\u0436\u0447\u0435."},
gWj(){return"\u0423\u043a\u0430\u0436\u0456\u0442\u044c \u043c\u0456\u0441\u0442\u0430, \u0440\u0430\u0439\u043e\u043d\u0438 \u0447\u0438 \u0440\u0435\u0433\u0456\u043e\u043d\u0438, \u0434\u0435 \u043f\u0440\u0430\u0446\u044e\u0454\u0442\u0435, \u0456 \u0432\u0456\u0434\u0441\u0442\u0430\u043d\u044c, \u043d\u0430 \u044f\u043a\u0443 \u0433\u043e\u0442\u043e\u0432\u0456 \u0432\u0438\u0457\u0436\u0434\u0436\u0430\u0442\u0438. \u0417\u0430\u0437\u043d\u0430\u0447\u0442\u0435, \u0447\u0438 \u043d\u0430\u0434\u0430\u0454\u0442\u0435 \u043f\u043e\u0441\u043b\u0443\u0433\u0438 \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0456\u0439\u043d\u043e."},
VQ(a){var s=""+a
return"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0454\u0442\u044c\u0441\u044f \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043a\u043e\u043c "+A.bA(a,s+" \u0434\u043d\u0456",this.a,s+" \u0434\u043d\u0456\u0432",s+" \u0434\u0435\u043d\u044c",s+" \u0434\u043d\u044f",null,null)},
