gBy(){return"\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0430 \u0441\u043e\u0431\u0456\u0432\u0430\u0440\u0442\u0456\u0441\u0442\u044c \u0432\u0430\u0448\u0438\u0445 \u043c\u0430\u0442\u0435\u0440\u0456\u0430\u043b\u0456\u0432 \u0434\u043b\u044f \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0431\u0435\u0437 \u0432\u0456\u0434\u0448\u043a\u043e\u0434\u043e\u0432\u0443\u0432\u0430\u043d\u043e\u0433\u043e \u043f\u043e\u0434\u0430\u0442\u043a\u0443 \u0437\u0430\u043a\u0443\u043f\u0456\u0432\u043b\u0456. \u041d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u0439\u0442\u0435 \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u0437\u0430\u043c\u043e\u0432\u043d\u0438\u043a\u0430, \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u0456 \u0442\u043e\u0432\u0430\u0440\u0438, \u043e\u0441\u043e\u0431\u0438\u0441\u0442\u0456 \u0432\u0438\u0442\u0440\u0430\u0442\u0438 \u0439 \u0431\u0430\u0433\u0430\u0442\u043e\u0440\u0430\u0437\u043e\u0432\u0456 \u0456\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0438. \u041d\u0430\u0446\u0456\u043d\u043a\u0430 \u0437\u0430\u043b\u0438\u0448\u0430\u0454\u0442\u044c\u0441\u044f \u0432 \u0431\u0430\u0437\u0456 \u043a\u043e\u043c\u0456\u0441\u0456\u0457."},
gBQ(){return"\u0423\u043a\u0430\u0436\u0456\u0442\u044c \u0442\u043e\u0447\u043d\u0438\u0439 \u043f\u043e\u0434\u0430\u0442\u043e\u043a \u0456\u0437 \u043f\u0440\u043e\u0434\u0430\u0436\u0443 \u0432 \u0446\u0456\u0439 \u043e\u043f\u043b\u0430\u0442\u0456 \u0437\u0430 \u0432\u0430\u0448\u0438\u043c \u0440\u0430\u0445\u0443\u043d\u043a\u043e\u043c. ClearFix \u043d\u0435 \u0432\u0438\u0437\u043d\u0430\u0447\u0430\u0454 \u043f\u043e\u0434\u0430\u0442\u043a\u043e\u0432\u0438\u0439 \u0441\u0442\u0430\u0442\u0443\u0441 \u0447\u0438 \u0441\u0442\u0430\u0432\u043a\u0438. \u041e\u0441\u043e\u0431\u0438\u0441\u0442\u0438\u0439 \u043f\u043e\u0434\u0430\u0442\u043e\u043a \u043d\u0430 \u0434\u043e\u0445\u0456\u0434 \u043d\u0435 \u0432\u0438\u0440\u0430\u0445\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f."},
